import {copyExample,decorateBrand,setupCodeBlocks} from '../app.mjs?v=85a37c256a13';
const code=(name)=>`<div class="code-window" data-code="${name}"><div class="code-header"><div class="tabs" role="tablist" aria-label="Code language"><button class="tab" role="tab" aria-selected="true" data-lang="py">Python</button><button class="tab" role="tab" aria-selected="false" data-lang="ts">TypeScript</button></div><button class="copy" data-copy aria-label="Copy code">Copy ⧉</button></div><pre><code></code></pre><div class="code-bottom"><span>SDK PREVIEW</span></div></div>`;
const table=(rows)=>`<table><thead><tr><th>Concept</th><th>Purpose</th></tr></thead><tbody>${rows.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table>`;
const escapeText=text=>text.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const setupCode=(label,text)=>`<div class="setup-code"><div class="code-header"><span>${label}</span><button class="copy" data-copy-text aria-label="Copy ${label}">Copy ⧉</button></div><pre><code>${escapeText(text)}</code></pre><p class="visually-hidden" role="status" data-copy-status></p></div>`;
const endpoint=()=>setupCode('MCP server URL','https://memory.preseen.ai/mcp/');
const installer=target=>setupCode('Plugin install command',`curl -fsSL https://memory.preseen.ai/v1/agent/install/script | bash -s -- --target ${target}`);
const guidance=()=>setupCode('Memory instructions',`Use CoSens to recall relevant preferences, decisions and project context before answering.
When I ask you to remember something, save it to CoSens.
Ask before uploading private files. Never report a save as complete until it succeeds.`);
const links=items=>`<div class="guide-links">${items.map(([key,label])=>`<a href="#${key}">${label} ↗</a>`).join('')}</div>`;
const connectNotice='Connect with OAuth. Available tools depend on your account, client and permissions.';
const serviceIdentity=()=>`<p><strong>CoSens</strong> uses the service at <code>memory.preseen.ai</code>. Sign-in screens and plugin installation may display <strong>Friday Memory</strong>, the current service name. For manually configured connectors, use <strong>CoSens</strong> as the display name. Installed plugins may expose the MCP server as <code>memory_connector</code>; keep the installer-provided name.</p>`;
export const pages={
pricing:{nav:'Plans & usage',title:'Experience storage. Processing and execution.',lead:'Choose a plan for the experience you keep and the work your AI does.',badge:'PLANS & USAGE',notice:'Memory connects today. Learn, SDK and Recipe management remain in preview. Plan access is arranged by email; this site does not take payment.',sections:[
['plans','Free, Plus and Pro',`<div class="pricing-doc-table" tabindex="0" role="region" aria-label="Plan comparison, scroll horizontally on small screens"><table><thead><tr><th>Plan</th><th>Monthly price</th><th>Experience storage</th><th>Monthly shared credit</th><th>Custom Recipes</th></tr></thead><tbody><tr><td>Free</td><td>$0</td><td>100 MB</td><td>$1</td><td>3</td></tr><tr><td>Plus</td><td>$9.9</td><td>1 GB</td><td>$10</td><td>10</td></tr><tr><td>Pro</td><td>$39.9</td><td>5 GB</td><td>$40</td><td>50</td></tr></tbody></table></div><p>Free has no time limit. Monthly shared credit is for <strong>experience processing and agent execution</strong>. These are plan allowances, not extra cash, fixed message counts or unlimited usage.</p><a class="text-link" href="/pricing/">Compare plans ↗</a>`],
['storage','Experience storage includes graph data',`<p>Saved content and graph data count toward experience storage. The allowance is not limited to uploaded source files. It does not describe how many original documents or messages you can save; processing can create additional graph data.</p><p>When storage is full, existing saved information remains readable; new writes stop until space is cleared or the plan is upgraded. Being within storage capacity does not provide unlimited processing.</p>`],
['processing','One balance for processing and execution',`<p>Experience processing includes memory processing and Recipe iteration. Agent execution also consumes model tokens. CoSens-provided model calls draw from the same shared credit balance.</p><p>Your external AI subscription and calls billed directly to your own model-provider account remain separate. Using your own model account does not remove the cost of other CoSens processing. Do not count a directly paid model call again against CoSens credit.</p><p>When the balance is exhausted, work that needs that credit pauses; add credit to continue. Contact us to arrange a top-up; this website does not collect payment.</p>`],
['recipes','Recipes and iterations',`<p>The Recipe allowance counts active custom Recipes. Versions do not count as additional Recipes. Iteration uses experience processing credit rather than an independent iteration-count allowance. Recipe management and the complete Learn loop remain in preview.</p>`],
['team','Shared team storage',`<p>Every plan supports team collaboration. Team experience storage is the sum of paid members’ allowances. Free members can collaborate without adding capacity. A Recipe allowance is not a count of included paid seats.</p>`],
['access','Arrange access',`<p>Start Free through the connection guides. For a paid plan, top-up or enterprise deployment, email <a href="mailto:hello@cosens.ai?subject=CoSens%20plans%20and%20usage">hello@cosens.ai</a>. Sending an enquiry does not activate a subscription or charge your account. This website does not process payments.</p>${links([['connect','Connect your AI'],['quickstart','SDK preview']])}`]]},
connect:{nav:'Start here',title:'Your first memory, connected.',lead:'Connect your AI, save something useful, then bring it back in a new conversation.',badge:'CONNECT COSENS',notice:connectNotice,sections:[
['connect','01 / Connect the AI you use',`<p>Choose your client and follow its guide. ChatGPT and Claude use remote MCP; Codex and Claude Code use plugins. Sign in with the same CoSens account in every client.</p>${links([['chatgpt','ChatGPT · MCP'],['claude','Claude · MCP'],['codex','Codex · plugin'],['claude-code','Claude Code · plugin'],['mcp','Other MCP clients']])}<p><strong>Connection check:</strong> ask your AI to read your CoSens profile using <code>user_get</code>. A successful tool response confirms access; an empty profile does not mean the connection failed. Saving requires write permission.</p>`],
['identity','The name you will see',`${serviceIdentity()}<p>CoSens is the experience layer you connect to your existing AI. It is not a separate chat app.</p>`],
['bring','02 / Save one useful source',`<p>Try a public sample before bringing your own material. It contains a pilot-launch decision and one unresolved approval.</p><a class="text-link" href="/assets/first-memory.md" download>Download pilot-launch sample (.md) ↗</a><p>In ChatGPT, enable the CoSens connection, attach the downloaded file and ask:</p>${setupCode('Save the sample','Save the attached pilot-launch sample to my CoSens memory. Tell me when processing is complete and it is ready to recall.')}<p>In Codex or Claude Code, give your agent the downloaded file path and ask it to upload that file to CoSens. Follow the upload command returned by the tool.</p><p>For Claude chat, or a read-only client, <a href="https://memory.preseen.ai/ingest" target="_blank" rel="noopener noreferrer">open Memory Ingest</a> with the same CoSens account, choose the intended personal or team space, and upload the file there. Then return to your connected AI.</p><p><strong>Save check:</strong> confirm the returned document identifier and completed processing. Wait for <code>recall_ready: true</code> when provided. Attaching a file or accepting an upload request alone does not mean recall is ready.</p>${links([['import','All document upload methods']])}`],
['ask','03 / Recall it in a new conversation',`<p>Open a new conversation, enable CoSens, and ask:</p>${setupCode('Recall the sample','What did we decide about the pilot launch, and what still needs approval? Use my saved pilot-launch sample and include the original source.')}<p><strong>Check against the sample:</strong> the pilot targets <strong>October 26, 2026</strong>; the <strong>security review</strong> still needs approval before launch. Open the returned source and check both statements. This is a walkthrough expectation from the sample, not a live result produced by this website.</p><p>To try another AI, connect it with the same CoSens account and ask the same question. It should retrieve the saved source rather than rely on the previous conversation. If no source is returned, check the account, enabled connection and document processing status.</p>${guidance()}`],
['control','Choose what becomes memory',`<p>Connecting does not import your entire chat history. Save information deliberately and upload only files you are authorized to share. Check the account and personal or team space before uploading.</p><p>To remove saved information, explicitly request deletion of the identified memory or document and inspect the result. Manage the client connection separately in that client’s settings; do not treat disconnecting as confirmation that saved material was deleted.</p>`],
['experience','From remembered context to better methods',`<p>Memory can bring the pilot decision into a new conversation today. Learn / RSI (recursive self-improvement) explores the next step: turning feedback such as “check unresolved approvals before setting a date” into a reusable method, validating it, then applying it to another launch.</p><p>Reason works through the problem. Remember supplies relevant experience. Improve changes the approach for a future task. Sensable AI is our name for that combination. The public MCP service provides Memory tools; the complete Learn loop is in preview.</p>${links([['learn','Learn preview & scope']])}<p><a class="text-link" href="/#experience">Explore Research, Writing, Analysis and Client work</a></p><p><a class="text-link" href="/#how-it-works">Explore the dinner example ↗</a></p>`],
['scope','What is available',`<p>The MCP service provides profile context, memory recall, exact source and timeline lookup, memory writes, document upload and deletion. Available actions depend on your account and client permissions.</p><p>The SDK, Recipe management and complete Learn loop are in preview. Gmail synchronization is coming soon.</p>${links([['apps','App connection status'],['quickstart','SDK interface preview']])}`]]},
 'import':{nav:'Bring your documents',title:'Upload once. Keep the context.',lead:'Bring your plans, notes and documents into CoSens, then use them in your next conversation.',badge:'DOCUMENT IMPORT',notice:'Choose the upload path that fits where you work.',sections:[
['chatgpt','Upload an attached file in ChatGPT',`<p>Select the CoSens connection, attach your document to the conversation and ask:</p>${setupCode('Upload prompt','Save the attached file to my CoSens memory so I can refer to it in future conversations.')}<p>ChatGPT provides a file reference to <code>document_upload</code>. CoSens retrieves the attached file and processes it. Attaching a file alone does not save it to long-term memory; ask for the upload explicitly.</p>${links([['chatgpt','ChatGPT setup']])}`],
['agents','Upload a local file with your coding agent',`<p>In Codex or Claude Code, point to the document in your workspace:</p>${setupCode('Local file prompt','Upload ./pilot-plan.pdf to my CoSens memory. Tell me when it is ready to recall.')}<p>The agent calls <code>document_upload</code> with the filename and receives a one-time upload URL and an upload command. It runs that command with the local file path; the shell sends the bytes. You do not need to encode the file or copy an access token.</p>${links([['codex','Codex plugin'],['claude-code','Claude Code plugin']])}`],
['console','Upload in the Memory Console',`<ol class="connection-list"><li>Open <strong>Memory Ingest</strong> in the Console.</li><li>Choose the intended personal or team space.</li><li>Select or drop your document, then start its upload.</li><li>Wait for processing to complete and for recall to be ready.</li></ol><a class="text-link" href="https://memory.preseen.ai/ingest" target="_blank" rel="noopener noreferrer">Open Memory Ingest ↗</a><p>This is also a convenient way to prepare documents before using them in Claude chat.</p>`],
['recall','Ask about it from any connected client',`${setupCode('Recall prompt','What did we decide about the pilot launch, and what is still unresolved? Use my saved documents and include sources.')}<p>Use the same CoSens account in each client. Your AI retrieves relevant saved context and uses it in the answer. In Claude chat, you can recall documents already imported through the Console, ChatGPT or a coding agent.</p><p>A successful upload returns a document identifier. Wait for processing to complete and <code>recall_ready: true</code> when provided before relying on recall.</p>`]]},
apps:{nav:'Connected apps',title:'Bring context from the places you work.',lead:'The goal: relevant information from your apps, ready in your AI conversation.',badge:'APP CONNECTIONS · COMING SOON',notice:'Gmail synchronization is not available from this website. No app authorization or email import runs on this page.',sections:[
['gmail','Gmail: the intended experience',`<p>After you authorize an app connection and its permitted messages have been synchronized into memory, your AI could answer: “Before my call with Alex, what did they ask for—and what did we promise?”</p><p>The homepage uses a dinner-planning scenario to show how preferences and feedback shape the next step. App connections are coming soon. The Gmail connector is in development and is not yet available for connection. No email authorization or synchronization is performed by the preview.</p>`],
['today','Use documents today',`<p>You can bring an authorized document into memory and ask your connected AI about its content. Exported notes or email content remain document imports; they do not establish a live Gmail connection.</p>${links([['import','Bring your documents']])}`],
['boundary','Connection and synchronization',`<p>Connecting an app directly to ChatGPT or Claude does not by itself save that app’s data to CoSens. A source integration must explicitly import the authorized material, finish processing and make it available to memory recall.</p>`]]},
chatgpt:{nav:'ChatGPT',title:'Bring your context into ChatGPT.',lead:'Connect the remote MCP service and use your saved context in conversation.',badge:'MCP CONNECTION',notice:connectNotice,sections:[
['identity','Before you connect',serviceIdentity()],
['requirements','Check account access',`<p>Your ChatGPT account and workspace must allow custom MCP connections. Full read/write support is subject to plan and workspace permissions; read-only access cannot save new memory. An administrator may need to add and enable the connection.</p>`],
['setup','Add the connection',`<ol class="connection-list"><li>On ChatGPT web, open <strong>Plugins</strong>, select the plus button, then <strong>Add custom MCP server</strong>. Some workspaces still use <strong>Settings → Apps → Create</strong>.</li><li>Name the connection <strong>CoSens</strong> and enter this public HTTPS endpoint.</li></ol>${endpoint()}<ol class="connection-list" start="3"><li>Choose OAuth and finish the sign-in and authorization shown by ChatGPT. The service may display Friday Memory.</li><li>Review the discovered tools, complete the connection and enable it in a conversation. In the current Plugins interface, type <strong>@</strong> and select it.</li></ol><p><a class="text-link" href="https://help.openai.com/en/articles/12584461-connecting-custom-mcp-servers-in-chatgpt" target="_blank" rel="noopener noreferrer">Official ChatGPT connection guide ↗</a></p>`],
['everyday','Use your documents in conversation',`<p>To save an attached file, select CoSens, attach the document and ask:</p>${setupCode('Save an attachment','Save the attached file to my CoSens memory and tell me when it is ready.')}<p>In a later conversation, select CoSens and ask:</p>${setupCode('Ask about saved work','What did we decide about the pilot launch? Include the original sources.')}<p>The host supplies the attached file reference; you do not paste file bytes into a tool call. For new information in a later message, select the connection again as required by your ChatGPT interface.</p>`],
['instructions','Help ChatGPT use your memory',`<p>Add these instructions to the appropriate personalization or connector guidance field, where your workspace permits it.</p>${guidance()}`],
['check','Check the connection',`<p>First ask it to read your CoSens profile using <code>user_get</code>. Then ask a question about a document you have already uploaded and processed. Ask for sources and check the tool result. Empty memory is not an authentication failure.</p><p>When a later message needs fresh data, select the connection again as required by your ChatGPT interface. Saving memory may require additional approval and write access.</p>${links([['import','Bring your documents']])}`]]},
claude:{nav:'Claude',title:'Bring your context into Claude.',lead:'Connect over remote MCP, sign in and enable memory in your conversation.',badge:'MCP CONNECTION',notice:connectNotice,sections:[
['identity','Before you connect',serviceIdentity()],
['setup','Add a remote connector',`<ol class="connection-list"><li>Open <strong>Customize → Connectors → Add custom connector</strong>. Team or Enterprise users may need an Owner to add it in Organization settings first.</li><li>Use the name <strong>CoSens</strong> and enter the server URL below.</li></ol>${endpoint()}<ol class="connection-list" start="3"><li>Use OAuth sign-in. Let Claude discover OAuth settings and complete its native sign-in flow.</li><li>Finish adding the connector, select <strong>Connect</strong> and complete authorization. The service may display Friday Memory.</li><li>Enable the connector from the conversation’s tools or connectors menu.</li></ol><p><a class="text-link" href="https://support.claude.com/en/articles/11175166-get-started-with-custom-connectors-using-remote-mcp" target="_blank" rel="noopener noreferrer">Official Claude connector guide ↗</a></p>`],
['everyday','Pick up your saved work',`<p>Enable CoSens in the conversation, then ask about a document you have already imported:</p>${setupCode('Ask Claude','What did we decide about the pilot launch, and what is still open? Use my saved documents and include sources.')}<p>CoSens supplies relevant context from the same account you use in your other clients. To add documents, use the Memory Console or upload through ChatGPT, Codex or Claude Code.</p>${links([['import','Bring your documents']])}`],
['instructions','Use relevant background',`${guidance()}<p>Use profile context for personal preferences and memory recall for prior decisions, project history and saved documents. Remote connectors run through Claude’s cloud service; a localhost address is not suitable for this setup.</p>`],
['check','Check the connection',`<p>Ask Claude to read your CoSens profile with <code>user_get</code>, then answer a question about processed material you have already saved. Review the returned sources. A successful read does not imply write permission.</p>${links([['import','Bring your documents'],['claude-code','Looking for Claude Code?']])}`]]},
codex:{nav:'Codex plugin',title:'Keep Codex in context.',lead:'Carry project decisions and confirmed context into the next coding session.',badge:'PLUGIN INSTALLATION',notice:'Requires the Codex CLI. Installation adds a remote MCP connection, memory skills and session hooks.',sections:[
['identity','Before you connect',serviceIdentity()],
['install','Install the plugin',`<p>Use the existing Memory Console MCP install action and select Codex, or run the service-hosted installer below. The installer is provided by the Memory service and currently uses the name Friday Memory.</p>${installer('codex')}<p>The hosted installer supplies the plugin package and checksum. It runs <code>codex mcp login memory_connector</code>; let Codex open its authorization page and wait for the browser callback. Do not copy access tokens into configuration.</p>`],
['everyday','Use it in your coding workflow',`${setupCode('Upload project context','Upload ./pilot-plan.pdf to my CoSens memory. Tell me when it is ready to recall.')}<p>Codex uses <code>document_upload</code> and runs the upload command returned by the tool with the local file path. Once processing finishes, ask about the document in this or another connected client.</p>${setupCode('Continue the work','Before changing this repository, recall our project decisions and explain the constraints I should preserve. Include sources.')}`],
['load','Start a fresh session',`<p>Restart Codex or start a fresh session so the plugin’s skills and hooks load. The plugin guides profile bootstrap, recall, deliberate memory writes and authorized document imports. It does not record every conversation automatically.</p>`],
['verify','Verify before relying on it',`<p>Check that <code>memory_connector</code> appears in the client’s MCP tools and that a read-only <code>user_get</code> call succeeds. Then ask: “What project decisions should I know before changing this repository?” A successful installation alone does not prove relevant memory exists.</p>`],
['manage','Manage the plugin',`<p>With the current plugin, ask Codex to check Friday Memory status, update it or reinstall it. The installed management skill handles the service-hosted workflow. Uninstallation requires an explicit request.</p>${links([['import','Bring project documents'],['claude-code','Claude Code plugin']])}`]]},
'claude-code':{nav:'Claude Code plugin',title:'Keep Claude Code in context.',lead:'Bring relevant project history into the work—and carry confirmed decisions forward.',badge:'PLUGIN INSTALLATION',notice:'Requires the Claude Code CLI. This plugin installation is separate from the Claude chat connector.',sections:[
['identity','Before you connect',serviceIdentity()],
['install','Install the plugin',`<p>Use the existing Memory Console MCP install action and select Claude Code, or run the service-hosted installer.</p>${installer('claude')}<p>The installer registers the remote HTTP MCP server through <code>claude mcp add</code> and installs a plugin through Claude Code’s native plugin CLI. It adds recall, remember, document and management skills, plus session hooks.</p>`],
['everyday','Bring project context into the work',`${setupCode('Upload a project document','Upload ./pilot-plan.pdf to my CoSens memory. Tell me when it is ready to recall.')}<p>Claude Code uses <code>document_upload</code> and runs the upload command returned by the tool with the local file path. Your file stays in the normal upload path; no manual encoding is needed.</p>${setupCode('Recall project decisions','What decisions from our earlier work apply to this task? Use my CoSens memory and include sources.')}`],
['authorize','Authorize and load',`<p>Complete the OAuth flow offered by Claude Code for <code>memory_connector</code>. The service may display Friday Memory. Restart Claude Code, or open <code>/plugin</code> and load the installed plugin before starting a fresh session.</p>`],
['check','Check the connection',`<p>Confirm the MCP tools are available and a read-only <code>user_get</code> call succeeds. Then ask about a saved project decision or processed document. Follow the client’s approvals for writes and uploads.</p>`],
['both','Use both coding clients',`<p>To install for Codex and Claude Code together, use this target list. Each client manages its own OAuth session.</p>${installer('codex,claude')}${links([['codex','Codex plugin'],['claude','Looking for Claude chat?']])}`]]},
mcp:{nav:'Other MCP clients',title:'One memory. Your MCP client.',lead:'Connect a client that supports remote Streamable HTTP MCP and OAuth.',badge:'MCP CONNECTION',notice:connectNotice,sections:[
['server','Register the remote server',`${endpoint()}<p>Use a remote Streamable HTTP connection and the client’s native OAuth flow. Let the client discover authorization settings. Do not configure a user ID, graph ID or copied bearer token.</p>`],
['tools','Discover the tools',table([['user_get','Read authenticated profile context.'],['memory_recall','Retrieve relevant saved information.'],['memory_get / timeline_get','Read exact sources or ordered history from known identifiers.'],['memory_write','Save confirmed durable context when authorized.'],['document_upload','Receive a host file reference, or request a one-time URL and upload command for a local file.'],['memory_delete','Remove exact memory only when explicitly requested.']])],
['guide','Provide usage instructions',`${guidance()}<p>A generic MCP connection does not install the lifecycle hooks available in the Codex and Claude Code plugins. Tool execution still depends on the host client.</p>`],
['check','Verify a read first',`<p>Discover the tools and call <code>user_get</code>. Then recall known saved information and inspect the sources. Authorize a test write only when you intend to persist it. There are no live tool calls on this documentation site.</p>`]]},

overview:{badge:'COSENS DOCS',notice:'Choose a connection guide or explore the SDK preview.',nav:'Overview',title:'A second brain for your agent.',lead:'Reason. Remember. Improve. Powered by LLM, Memory and Learn.',sections:[
['paths','Connect it. Explore the SDK.',links([['connect','Connect your AI'],['quickstart','Explore SDK preview']])],
['idea','The idea',`<p>CoSens is building Sensable AI: AI that reasons with your experience and learns from your feedback to help with the next problem. For developers, CoSens adds an independent experience layer to an agent. The agent reasons with an LLM, recalls relevant background from Memory, and uses Learn to improve its methods through outcomes and feedback.</p>`],
['terms','AI, agent and LLM',table([['AI','The assistant a person uses, such as ChatGPT or Claude.'],['Agent','The application that handles a task and uses the model, Memory and Learn.'],['LLM','The model component that provides general reasoning.']])],
['runtime','How the SDK works',`<p>During a task, the agent uses relevant context. Afterward, task results and feedback can develop candidate methods. Methods need validation before reuse within their scope.</p><a class="text-link" href="/build/#how-it-works">Explore the SDK workflow ↗</a>`],
['parts','Three parts, one brain',table([['LLM','Reason — work through the current task.'],['Memory','Remember — bring relevant decisions, preferences and prior work into the task.'],['Learn','Improve — develop and validate reusable methods from outcomes and feedback.']])+`<p>Learn turns work and feedback into reusable ways of working, represented as Recipes.</p>`],
['integration','Add one line',`<p>Create your client as usual, then wrap that existing instance. This is the target integration shape, not a claim of universal client compatibility.</p>${code('wrapper')}`],
['preview','Preview status',`<p>These docs present the SDK preview. Wrapper syntax, management methods, parameter names and examples are part of the SDK preview, not a published release contract. No package is installed and no live API calls run on this site.</p><p>Authentication, supported client versions, data connections and setup steps will be documented with the released SDK. “Add one line” refers to the wrapper, not a promise that these prerequisites disappear.</p>`]]},
quickstart:{nav:'Quickstart',badge:'SDK INTERFACE PREVIEW',notice:'This is an interface preview, not an installable SDK release. Package and setup instructions are coming with the SDK release. Use the connection guides for Memory today.',title:'Add one line. Bring your experience.',lead:'Explore the proposed wrapper, Memory, Recipe and Feedback APIs.',sections:[
['available','Use Memory today',`<p>Connect ChatGPT, Claude, Codex or Claude Code through the available MCP service and plugins. This route does not require the preview SDK.</p>${links([['connect','Connect your AI']])}`],
['wrapper','01 / Wrap your existing client',`<p>Keep the client initialization. Add one line after it.</p>${code('wrapper')}<p>Python and TypeScript show the same integration. This preview focuses on the integration shape. Installation, authentication and supported client versions will be documented with the SDK release.</p>`],
['memory','02 / Work with Memory',`<p>Retrieve relevant context before the task. Inspect and manage remembered information directly through the proposed Memory API.</p>${code('recall')}<a class="text-link" href="#memory">Memory API →</a>`],
['recipes','03 / Work with Recipes',`<p>Inspect the method, version, status and applicable scope. Finding a candidate does not make it adopted.</p>${code('recipe')}<a class="text-link" href="#recipes">Recipe API →</a>`],
['feedback','04 / Feed the learning loop',`<p>Connect the review to the exact output and preserve the reviewer’s reason. Feedback is material for learning; it is not proof that a new method works.</p>${code('feedback')}<a class="text-link" href="#feedback">Feedback API →</a>`]]},
memory:{nav:'Memory API',title:'Memory API',lead:'Give a task its background—and keep control of that background.',sections:[
['retrieve','Retrieve task context',`<p>Ask for context relevant to a specific job. Preserve its source and distinguish confirmed decisions from assumptions.</p>${code('recall')}`],
['manage','Inspect and update memory',`<p>The management interface in this preview lets developers inspect memory records and correct their contents. The record IDs below are sample identifiers; API signatures and write semantics are in preview.</p>${code('memory')}`],
['control','Control and access',`<p>Access must follow authenticated authorization. A client-provided label is not a permission boundary. Production integration must specify retention, update/delete behavior and data-source permissions before they can be relied on.</p><p>Do not treat every task instruction as a durable preference. Missing or unavailable retrieval should remain visible rather than look like a successful recall.</p>`]]},
learn:{nav:'Learn',title:'Improve through experience.',lead:'Learn is the tool. Improve is the outcome. Turn tasks and feedback into tested methods for the problems your users face.',sections:[
['signal','Capture the task and review',`<p>Connect the task, context, method, output, feedback and actual result. Preserve versions so a later correction does not rewrite what happened earlier.</p>${code('feedback')}<a class="text-link" href="#feedback">Feedback API →</a>`],
['reason','Confirm what the feedback means',`<p>A correction may indicate missing context, an unsuitable method or a changed requirement. Keep a reviewer’s confirmed reason separate from a model’s explanation. Unanswered questions remain unanswered.</p>`],
['learn','Develop and test a method',`<p>Learn develops candidate methods, checks new tasks, boundary cases and regressions, and supports reuse only within the scope backed by evidence.</p><p>The near-term direction is experience learning through context and reusable methods. It does not imply automatic model-weight updates, consciousness, or that every interaction improves capability.</p>`],
['loop','Keep learning from use',`<p>Task → feedback → candidate method → validation → applicable future use. Later outcomes provide new evidence. Use is learning material, not a guarantee of monotonic improvement.</p>`]]},
recipes:{nav:'Recipe API',title:'Recipe API',lead:'A Recipe is a reusable way of working. Inspect its method, version and applicable scope.',sections:[
['example','A method, not a saved answer',`<p>For dinner planning: compare arrival time with last-order time before recommending a venue. Diet and atmosphere remain separate constraints supplied by Memory.</p><p>The interactive dinner example shows the difference between a saved preference and a reusable method. Its responses and venue data are scripted.</p>`],
['manage','Inspect Recipes',`<p>The management API in this preview exposes methods for inspection and selection in your application. These interfaces are in preview.</p>${code('recipe')}`],
['edit','Edit the method and scope',`<p>Management action in the SDK preview: edit a method against a base version and define its intended task scope. In this design, editing creates a new candidate version. It does not silently replace a validated version or approve reuse.</p>${code('recipeEdit')}<p>The signature and version semantics may change before release. Independent checks are still required before adopting the new version.</p>`],
['fields','What to inspect',table([['Method','The steps and judgments to apply.'],['Version','The exact method that was tested.'],['Status','Candidate, validated or adopted; never interchangeable.'],['Scope','Tasks and prerequisites supported by the evidence.'],['Validation','New-task, boundary-case and regression evidence.']])],
['adoption','Management is not validation',`<p>Inspecting or editing a method does not prove it is safe to reuse. A changed version must be evaluated before adoption. A Recipe describes how to work; task-specific evaluation criteria describe what a good outcome means.</p>`]]},
feedback:{nav:'Feedback API',title:'Feedback API',lead:'Connect a correction to the task and output it refers to.',sections:[
['submit','Submit feedback',`<p>Use <code>client.feedback.submit</code> to provide feedback on a specific task and output version. This is an SDK preview interface; signatures and return types are not a released contract.</p>${code('feedback')}`],
['parameters','Parameters',table([['task_id / taskId','The task this feedback concerns.'],['artifact_version / artifactVersion','The exact output version being reviewed.'],['message','The correction or feedback in the reviewer’s own words.'],['reason','The reviewer’s explanation, when provided; do not invent one.']])],
['result','What submission means',`<p>Submission links feedback to its task and output. It does not confirm that a candidate method has been created, validated or adopted. The return schema is part of the SDK preview and is not yet a published contract.</p>`],
['learning','From feedback to improvement',`<p>Learn considers feedback alongside task context and outcomes. Candidate methods need validation before reuse.</p>${links([['learn','Learn'],['recipes','Recipe API'],['validation','Validation']])}`]]},
validation:{nav:'Validation',title:'Check that improvements carry forward.',lead:'A method should help with the next applicable task, not just the original example.',sections:[
['common','Use a common standard',`<p>Compare baseline and candidate on the same cases, inputs and evaluation criteria. Keep learning material separate from independent evaluation material.</p>`],
['checks','Check transfer and boundaries',table([['New tasks','Does the method help on independent work within its scope?'],['Boundary cases','Does it stay out of tasks where it does not belong?'],['Regressions','Does it preserve important behavior on earlier work?']])],
['result','Verify the outcome',`<p>A candidate, a validation report, an adopted method and later successful use are different states. For external actions, match the completion claim to the observed result, not just a successful intermediate call.</p><p>The dinner example shows a timing check applied to a new evening. A passing scripted case is not proof of general improvement; a released system needs independent evaluation.</p>`]]},
api:{nav:'API Reference',title:'API Reference',lead:'Explore the proposed client, Memory, Recipe and feedback interfaces.',sections:[
['wrapper','Client wrapper',`<p>The confirmed product direction wraps an existing LLM client. Exact constructors, supported SDK versions and request semantics are not yet a published contract.</p>${code('wrapper')}`],
['memory','Memory API',`<p>Proposed methods: <code>client.memory.recall</code>, <code>client.memory.list</code>, <code>client.memory.update</code>. Use the Memory article to explore context retrieval and management.</p>${code('memory')}`],
['recipes','Recipe API',`<p>Proposed methods: <code>client.recipes.list</code>, <code>client.recipes.get</code> and <code>client.recipes.update</code>. Inspect or edit method versions and scope; retrieval and editing do not imply adoption.</p>${code('recipe')}${code('recipeEdit')}`],
['feedback','Feedback API',`<p><code>client.feedback.submit</code> connects feedback to a task and output version. Authentication must determine identity; accepting a feedback event does not mean learning or validation has completed.</p>${code('feedback')}<a class="text-link" href="#feedback">Feedback API →</a>`],
['status','Release status',`<p>The interfaces on this page are in preview. There is no executable SDK package, production endpoint, compatibility certification or measured learning result established by this preview. Do not use these examples as a released integration contract.</p>`]]}
};
const content=document.querySelector('#doc-content');
content.tabIndex=-1;
document.querySelector('.skip').addEventListener('click',event=>{
  event.preventDefault();content.focus();content.scrollIntoView();
});
const menu=document.querySelector('#doc-menu');
const layout=document.querySelector('.docs-layout');
function render(){
  const key=location.hash.slice(1)||'connect';
  const page=pages[key];
  if(!page){content.innerHTML='<div class="preview-badge">DOCUMENTATION</div><h1>Page not found.</h1><p>This preview does not contain that article.</p><a class="text-link" href="#overview">Back to overview →</a>';document.querySelector('#doc-toc').replaceChildren();return;}
  document.title=`${page.nav} — CoSens Docs`;
  content.innerHTML=`<div class="breadcrumb">Docs / ${page.nav}</div><span class="preview-badge">${page.badge||'SDK PREVIEW'}</span><h1>${page.title}</h1><p class="doc-lead">${page.lead}</p><div class="notice">${page.notice||'SDK preview · interfaces may change.'}</div>${page.sections.map(([id,title,body])=>`<section><h2 id="${id}">${title}</h2>${body}</section>`).join('')}<div class="doc-pager"><a href="#overview">← Overview</a><a href="/">Connect CoSens ↗</a></div>`;
  document.querySelectorAll('.doc-nav-link').forEach(link=>{if(link.hash===`#${key}`)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
  const toc=document.querySelector('#doc-toc');toc.replaceChildren();
  page.sections.forEach(([id,title])=>{const link=document.createElement('a');link.href=`#${key}`;link.textContent=title;link.addEventListener('click',event=>{event.preventDefault();document.getElementById(id).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});toc.append(link);});
  decorateBrand(content);
  setupCodeBlocks(content);
  content.querySelectorAll('[data-copy-text]').forEach(button=>button.addEventListener('click',async()=>{
    const block=button.closest('.setup-code');
    const status=await copyExample(block.querySelector('code').textContent,navigator.clipboard);
    button.textContent=status;block.querySelector('[data-copy-status]').textContent=status;
  }));
  layout.classList.remove('menu-open');menu.setAttribute('aria-expanded','false');
}
const search=document.querySelector('#doc-search');
const results=document.querySelector('#search-results');
search.addEventListener('input',()=>{
  const query=search.value.trim().toLowerCase();
  document.querySelector('#doc-nav-groups').hidden=!!query;results.hidden=!query;results.replaceChildren();
  if(!query)return;
  const matches=Object.entries(pages).filter(([,p])=>[p.nav,p.title,p.lead,...p.sections.flat()].join(' ').toLowerCase().includes(query));
  if(!matches.length){const empty=document.createElement('div');empty.className='empty-results';empty.textContent='No matching pages. Try “feedback” or “scope”.';results.append(empty);}
  for(const [key,page]of matches){const link=document.createElement('a');link.href=`#${key}`;link.className='search-result';const title=document.createElement('strong');title.textContent=page.nav;const desc=document.createElement('small');desc.textContent=page.title;link.append(title,desc);link.addEventListener('click',()=>{search.value='';results.hidden=true;document.querySelector('#doc-nav-groups').hidden=false;});results.append(link);}
});
menu.addEventListener('click',()=>{const open=layout.classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open));});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
